        // fall back to the old direct-<.volume> path by clearing the WebAudio handles.
        menuBgmMediaSrc = null;
        menuBgmMenuGain = null;
        menuBgmAnalyser = null;
        menuBgmTimeBuf = null;
        menuBgmFreqBuf = null;
        menuBgmAudio.volume = calcMusicLevel();
