        P([[0.32, 0.085], [0.34, 0.085, 0.004], [0.35, 0.07], [0.35, -0.05, 0.006], [0.325, -0.05, 0.006], [0.32, 0.06]], 0.05, M.rubber, { bevel: 0.005 }, stockGrp);
        // curved magazine
