    function bindVolSlider(rangeEl, labelEl, key, applyFn) {
      rangeEl.addEventListener("input", () => {
        const v = (+rangeEl.value || 0) / 100;
        gameSettings[key] = v;
        labelEl.textContent = `${rangeEl.value}%`;
        applyFn();
      });
      // Persist only when the drag settles — 'input' fires ~60-100x/sec while dragging.
      rangeEl.addEventListener("change", saveGameSettings);
    }
    bindVolSlider(rngMasterVol, lblMasterVol, "masterVolume", applyAudioVolumes);
    bindVolSlider(rngMusicVol, lblMusicVol, "musicVolume", applyAudioVolumes);
    bindVolSlider(rngSfxVol, lblSfxVol, "soundVolume", applyAudioVolumes);

    // (The "Animated background light visual" toggle was removed — the menu-wall
    // 3D scene is always on. The boot path unconditionally calls
    // initMenuWallBackdrop().)

    /**
     * The DPI field + eDPI / cm-360 readout are built here instead of in index.html so this
     * whole sensitivity change stays inside main.js. DPI is not used by the aim maths at all
     * — it exists purely so the readout can show numbers you can compare with other games.
     */
    let _dpiInput = null;
    let _sensReadoutEl = null;

    function buildSensitivityControls() {
      const hint = document.getElementById("lookSensHint");
      if (!hint || _dpiInput) return;

      const row = document.createElement("div");
      row.style.cssText = "display:flex;align-items:center;gap:10px;margin-top:12px;flex-wrap:wrap;";

      const lab = document.createElement("label");
      lab.textContent = tr("mouseDpiLabel", "Mouse DPI");
      lab.style.cssText = "font-size:13px;opacity:0.9;font-family:var(--game-font-ui);";

      const inp = document.createElement("input");
      inp.type = "number";
      inp.min = String(MOUSE_DPI_MIN);
      inp.max = String(MOUSE_DPI_MAX);
      inp.step = "50";
      inp.value = String(clampMouseDpi(gameSettings.mouseDpi));
      inp.style.cssText =
        "width:110px;padding:7px 10px;font-size:14px;font-family:var(--game-font-ui);" +
        "background:#0d111b;color:#fff;border:1.5px solid rgba(120,200,255,0.55);" +
        "border-radius:6px;outline:none;";
      inp.addEventListener("input", () => {
        gameSettings.mouseDpi = clampMouseDpi(+inp.value);
        syncSensReadout();
      });
      inp.addEventListener("change", () => {
        inp.value = String(clampMouseDpi(gameSettings.mouseDpi));
        saveGameSettings();
      });

      const readout = document.createElement("div");
      readout.style.cssText =
        "font-size:13px;font-family:var(--game-font-ui);color:#7ec8ff;letter-spacing:0.5px;";

      row.appendChild(lab);
      row.appendChild(inp);
      row.appendChild(readout);
      hint.parentNode.insertBefore(row, hint);

      _dpiInput = inp;
      _sensReadoutEl = readout;

      hint.textContent = tr(
        "sensHintNew",
        "Same maths as other shooters: degrees/count = sensitivity × 0.022. " +
          "DPI is only used to show eDPI and cm/360 — it does not change your aim."
      );
      syncSensReadout();
    }

    function syncSensReadout() {
      if (!_sensReadoutEl) return;
      if (_dpiInput && document.activeElement !== _dpiInput) {
        _dpiInput.value = String(clampMouseDpi(gameSettings.mouseDpi));
      }
      const edpi = getEdpi();
      const cm = getCmPer360();
      _sensReadoutEl.textContent = `eDPI ${Math.round(edpi)}  ·  ${cm.toFixed(1)} cm/360°`;
    }

    /**
     * Sensitivity / ADS-multiplier sliders. The <input> min/max/step come from the old
     * percent scale, so they are re-ranged here rather than in index.html — that keeps this
     * whole change JS-only.
     */
    function bindSensSlider(rangeEl, labelEl, key, clampFn, min, max, step, fmt) {
      if (!rangeEl || !labelEl) return;
      rangeEl.min = String(min);
      rangeEl.max = String(max);
      rangeEl.step = String(step);
      rangeEl.addEventListener("input", () => {
        const v = clampFn(+rangeEl.value);
        gameSettings[key] = v;
        rangeEl.value = String(v);
        labelEl.textContent = fmt(v);
        syncSensReadout();
      });
      rangeEl.addEventListener("change", saveGameSettings);
    }
    bindSensSlider(rngLookSens, lblLookSens, "sensitivity", clampSens,
      SENS_MIN, SENS_MAX, 0.01, (v) => v.toFixed(2));
    bindSensSlider(rngAdsLookSens, lblAdsLookSens, "adsSensMultiplier", clampAdsSensMul,
      ADS_SENS_MUL_MIN, ADS_SENS_MUL_MAX, 0.01, (v) => `${v.toFixed(2)}×`);

    function cycleQuality(delta) {
      gameSettings.qualityIndex = (gameSettings.qualityIndex + delta + QUALITY_LEVELS.length) % QUALITY_LEVELS.length;
      resetAdaptiveRenderControl(true);
      syncSettingsUI();
      saveGameSettings();
      applyGraphicsQuality();
    }
    btnQualityPrev.addEventListener("click", () => cycleQuality(-1));
    btnQualityNext.addEventListener("click", () => cycleQuality(1));

    for (const id of ["btnPostPrev", "btnPostNext"]) {
      const btn = document.getElementById(id);
      if (btn) btn.addEventListener("click", () => {
        gameSettings.postFx = id === "btnPostNext";
        resetAdaptiveRenderControl(true);
        syncGameRendererSize();
        syncSettingsUI();
        saveGameSettings();
      });
    }
    btnTexturePrev.addEventListener("click", () => {
      gameSettings.texturesOn = false;
      syncSettingsUI();
      saveGameSettings();
      applyWallTexture();
      compileSceneShaders();
    });
    btnTextureNext.addEventListener("click", () => {
      gameSettings.texturesOn = true;
      syncSettingsUI();
      saveGameSettings();
      applyWallTexture();
      compileSceneShaders();
    });

    const btnSkipClickOff = document.getElementById("btnSkipClickOff");
    const btnSkipClickOn = document.getElementById("btnSkipClickOn");
    if (btnSkipClickOff) {
      btnSkipClickOff.addEventListener("click", () => {
        gameSettings.skipClickToPlay = false;
        syncSettingsUI();
        saveGameSettings();
        updateClickHintVisibility();
      });
    }
    if (btnSkipClickOn) {
      btnSkipClickOn.addEventListener("click", () => {
        gameSettings.skipClickToPlay = true;
        syncSettingsUI();
        saveGameSettings();
        updateClickHintVisibility();
        if (gameWorldReady && player.health > 0) tryAutoCapturePointer();
      });
    }

    function cycleRenderDistance(delta) {
      const n = RENDER_DISTANCE_LEVELS.length;
      gameSettings.renderDistanceIndex = (gameSettings.renderDistanceIndex + delta + n) % n;
      syncSettingsUI();
      saveGameSettings();
      applySceneFogAndCameraFar();
    }
    btnRenderDistPrev.addEventListener("click", () => cycleRenderDistance(-1));
    btnRenderDistNext.addEventListener("click", () => cycleRenderDistance(1));

    function cycleLanguage(delta) {
      const i = LANGUAGE_OPTIONS.indexOf(gameSettings.language);
      const next = (i + delta + LANGUAGE_OPTIONS.length) % LANGUAGE_OPTIONS.length;
      gameSettings.language = LANGUAGE_OPTIONS[next];
      syncSettingsUI();
      saveGameSettings();
      updateHud();
    }
    btnLangPrev?.addEventListener("click", () => cycleLanguage(-1));
    btnLangNext?.addEventListener("click", () => cycleLanguage(1));

    syncSettingsUI();

    window.addEventListener("resize", () => {
      syncGameRendererSize();
    });
    document.addEventListener("fullscreenchange", () => {
      _rendererSyncWarmupFrames = Math.max(_rendererSyncWarmupFrames, 120);
      syncGameRendererSize();
      requestAnimationFrame(() => syncGameRendererSize());
    });
    window.addEventListener("orientationchange", () => {
      const bump = () => {
        syncGameRendererSize();
        try {
          resizeMenuWallBackdrop();
        } catch (_) {}
      };
      bump();
      requestAnimationFrame(bump);
      setTimeout(bump, 80);
      setTimeout(bump, 280);
    });
    window.addEventListener("load", () => {
      _rendererSyncWarmupFrames = Math.max(_rendererSyncWarmupFrames, 200);
      syncGameRendererSize();
      requestAnimationFrame(() => syncGameRendererSize());
      try {
        resizeMenuWallBackdrop();
      } catch (_) {}
      [16, 120, 380].forEach((ms) =>
        setTimeout(() => {
          syncGameRendererSize();
          try {
            resizeMenuWallBackdrop();
          } catch (_) {}
        }, ms)
      );
    });
    window.addEventListener("pageshow", () => {
      _rendererSyncWarmupFrames = Math.max(_rendererSyncWarmupFrames, 160);
      syncGameRendererSize();
      requestAnimationFrame(() => syncGameRendererSize());
      try {
        resizeMenuWallBackdrop();
      } catch (_) {}
    });
    document.addEventListener("visibilitychange", () => {
      if (document.visibilityState === "visible") {
        _rendererSyncWarmupFrames = Math.max(_rendererSyncWarmupFrames, 120);
        syncGameRendererSize();
        requestAnimationFrame(() => syncGameRendererSize());
        try {
          resizeMenuWallBackdrop();
        } catch (_) {}
      }
    });
    try {
      if (window.visualViewport) {
        window.visualViewport.addEventListener("resize", () => syncGameRendererSize());
        window.visualViewport.addEventListener("scroll", () => syncGameRendererSize());
      }
    } catch (_) {}
    try {
      if (typeof ResizeObserver !== "undefined") {
        const ro = new ResizeObserver(() => {
          syncGameRendererSize();
          try {
            resizeMenuWallBackdrop();
          } catch (_) {}
        });
        if (app) ro.observe(app);
        if (document.documentElement) ro.observe(document.documentElement);
      }
    } catch (_) {}
    try {
      renderer.domElement.addEventListener("webglcontextrestored", () => {
        _rendererSyncWarmupFrames = Math.max(_rendererSyncWarmupFrames, 160);
        syncGameRendererSize();
        requestAnimationFrame(() => syncGameRendererSize());
      });
    } catch (_) {}

    // Backpack screen. Built last, once every declaration above has been evaluated —
    // calling it earlier hit the temporal dead zone on its own `let`s and aborted the
    // whole module. Guarded so a failure here can never take the game down with it.
    try {
      buildLoadoutPanel();
      syncLoadoutPanel();
    } catch (e) {
      console.warn("[loadout] panel init failed:", e);
    }

    // Test hook, only with ?debug=1: lets a script drop the player anywhere on a gauntlet course
    // and read the course back, so levels can be checked without playing them through.
    if (new URLSearchParams(location.search).get("debug") === "1") {
      window.__zn = {
        THREE, player, camera, state, keys, scene, renderer,
        get course() { return gauntletCourse; },
        get progress() { return gauntletState; },
        get post() { return postFx; },
        setPost(on) {
          gameSettings.postFx = on;
          resetAdaptiveRenderControl(true);
          syncGameRendererSize();
        },
        unpause() { hidePause(); },
        goto(arc, height = 0, lookAhead = 6) {
          const route = gauntletCourse.path;
          const i = gauntletIndexAtArc(Math.max(0, arc)), c = route[i], n = route[Math.min(route.length - 1, i + lookAhead)];
          const dx = n.x - c.x, dz = n.z - c.z;
          player.position.set(c.x, c.y + 1.65 + height, c.z);
          player.yaw = Math.atan2(-dx, -dz);
          player.velocityY = 0;
          player.onGround = height === 0;
          gauntletState.progressIdx = i;
          camera.position.copy(player.position);
          return { x: c.x, y: c.y, z: c.z };
        },
        look(yaw, pitch = 0) { player.yaw = yaw; player.pitch = pitch; },
        tp(x, y, z, yaw = 0, pitch = 0) { player.position.set(x, y + 1.65, z); player.velocityY = 0; player.yaw = yaw; player.pitch = pitch; camera.position.copy(player.position); },
        get pvp() { return pvpWorld; },
        get spawns() { const d = pvpDef(CURRENT_MAP); return d ? d.spawns : null; },
        collidesAt(x, y, z) { return collidesWithWalls(new THREE.Vector3(x, y + 1.65, z)); },
        collides(dx = 0, dz = 0) { return collidesWithWalls(new THREE.Vector3(player.position.x + dx, player.position.y, player.position.z + dz)); },
        near(r = 2.5) {
          const out = [];
          forEachNearbyWallBox(player.position.x, player.position.z, (b) => {
            if (b.min.x - r < player.position.x && b.max.x + r > player.position.x && b.min.z - r < player.position.z && b.max.z + r > player.position.z) {
              out.push([+b.min.x.toFixed(2), +b.min.y.toFixed(2), +b.min.z.toFixed(2), +b.max.x.toFixed(2), +b.max.y.toFixed(2), +b.max.z.toFixed(2), b.wideTop ? "deck" : "", b.enemyOnly ? "enemy" : "", b.dyn ? "dyn" : ""].join(" "));
            }
          });
          return out;
        },
        /**
         * A clean still of the current view (no HUD, no weapon) at the given size, as a JPEG data URL.
         * This is how the map-select covers in images/maps/ are made: teleport with `tp()`, then `capture()`.
         */
        capture(w = 1320, h = 780, quality = 0.9) {
          const size = renderer.getSize(new THREE.Vector2()), dpr = renderer.getPixelRatio(), aspect = camera.aspect;
          const hidden = camera.children.filter((c) => c.visible);
          hidden.forEach((c) => { c.visible = false; });
          renderer.setPixelRatio(1); renderer.setSize(w, h, false);
          camera.aspect = w / h; camera.updateProjectionMatrix();
          let usedPost = false;
          if (postFx && postFxWanted()) { try { postFx.setSize(w, h, 1); postFx.update(0, { waterTime: Date.now() / 1000 % 1024 }); postFx.render(0); usedPost = true; } catch (_) { /* raw render below */ } }
          if (!usedPost) renderer.render(scene, camera);
          const url = renderer.domElement.toDataURL("image/jpeg", quality);
          renderer.setPixelRatio(dpr); renderer.setSize(size.x, size.y, false);
          camera.aspect = aspect; camera.updateProjectionMatrix();
          if (postFx) postFx.setSize(size.x, size.y, dpr);
          hidden.forEach((c) => { c.visible = true; });
          return url;
        },
        stats() { return { boxes: wallBoxes.length, meshes: wallMeshes.length, props: gauntletProps.length, path: gauntletCourse?.path.length, length: gauntletCourse?.length, checkpoints: gauntletCourse?.checkpoints.length, calls: renderer.info.render.calls, tris: renderer.info.render.triangles }; },
        /** Where a ray from (ox,oy,oz) along (dx,dy,dz) meets the first enemy: { t, zone } or null (hit-table testing). */
        enemyHit(ox, oy, oz, dx, dy, dz) {
          const ray = new THREE.Raycaster(new THREE.Vector3(ox, oy, oz), new THREE.Vector3(dx, dy, dz).normalize(), 0, 200);
          let best = null;
          for (const e of state.enemies) {
            if (!e.alive) continue;
            e.group.updateMatrixWorld(true);
            const h = enemyHitAlongRay(ray, e);
            if (h && (!best || h.t < best.t)) best = { t: +h.t.toFixed(2), zone: h.zone };
          }
          return best;
        },
        /** Fires a boss fireball from a point with a velocity (explosion testing); fx() reports what is alive. */
        ball(ox, oy, oz, vx, vy, vz, damage = 24, hell = false) { return spawnBossProjectile(ox, oy, oz, vx, vy, vz, damage, null, null, { hell, floorY: 0 }); },
        fx() { return { balls: bossProjectiles.length, blasts: bossBlasts.length, scorch: bossScorches.length, lights: bossFxLights.map((l) => +l.intensity.toFixed(1)) }; },
        /** Is the boss (standing at x, z facing yaw) overlapping a wall? (footprint testing) */
        bossBlocked(x, z, yaw) { const b = state.enemies.find((e) => e.isCreatureBoss && !e.trainingDummy); return b ? bossBlockedAt(b, x, z, yaw) : null; },
        /** Runs the enemy simulation for `seconds` of game time at a fixed step, without waiting for frames (boss testing). */
        sim(seconds = 1, step = 0.033, onStep = null) {
          for (let t = 0; t < seconds; t += step) {
            updateEnemies(step); updateBossProjectiles(step); updateBossTelegraphs();
            if (onStep) onStep(t);
          }
          return state.enemies.filter((e) => e.isBoss).map((b) => ({ anim: b.bossAnimState, x: b.group.position.x, z: b.group.position.z, hp: b.hp }));
        },
      };
    }
